function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const sortedKeys = (m) => [...m.keys()].sort(cmp)

function render(node, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  switch (node.type) {
    case 'table': {
      const ks = sortedKeys(node.m)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${render(node.m.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!node.items.length) return '[]'
      return '[\n' + node.items.map((v) => pad + render(v, ind + 1)).join(',\n') + '\n' + end + ']'
    default:
      return JSON.stringify(node.v)
  }
}

export function toJson(root) {
  return render(root, 0) + '\n'
}

