  const out = []
  const walk = (node, path) => {
    if (node.type === 'table') {
      for (const k of sortedKeys(node.m)) {
        const p = path === null ? k : `${path}.${k}`
        out.push(`${p} ${node.m.get(k).type}`)
        walk(node.m.get(k), p)
      }
    } else if (node.type === 'array') {
      node.items.forEach((v, i) => {
        const p = `${path}[${i}]`
        out.push(`${p} ${v.type}`)
        walk(v, p)
      })
    }
  }
  walk(root, null)
  return out.map((l) => l + '\n').join('')
}
