export class ParseError extends Error {
  constructor(line, reason) {
    super(reason)
    this.line = line
    this.reason = reason
  }
}

const newTable = () => ({ type: 'table', m: new Map(), defined: false })
const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
