    this.i++
    const t = newTable()
    this.ws()
    if (this.peek() === '}') {
      this.i++
      return t
    }
    for (;;) {
      this.ws()
      if (this.i >= this.s.length || this.atEnd()) this.fail('unterminated inline table')
