      this.ws()
      const c = this.peek()
      if (c === '}') {
        this.i++
        return t
      }
      if (c !== ',') this.fail('unterminated inline table')
      this.i++
    }
  }
}

function assign(table, prefix, names, v, p) {
  let cur = table
  let path = prefix.slice()
  for (let k = 0; k < names.length - 1; k++) {
    path.push(names[k])
    let next = cur.m.get(names[k])
    if (next === undefined) {
      next = newTable()
      cur.m.set(names[k], next)
    } else if (next.type === 'array' && next.aot) {
      next = next.items[next.items.length - 1]
    } else if (next.type !== 'table') {
      p.fail(`${path.join('.')} is not a table`)
    }
    cur = next
  }
  const last = names[names.length - 1]
  path.push(last)
  if (cur.m.has(last)) p.fail(`key ${path.join('.')} is defined twice`)
  cur.m.set(last, v)
}

export function parseDocument(lines) {
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((line, idx) => {
    const p = new LineParser(line, idx + 1)
    p.ws()
    if (p.i >= line.length || line[p.i] === '#' || line[p.i] === ';') return
    if (line[p.i] === '[') {
      p.i++
      const aot = p.peek() === '['
      if (aot) p.i++
      p.ws()
      const names = p.dotted()
      p.ws()
      for (let k = 0; k < (aot ? 2 : 1); k++) {
        if (p.peek() !== ']') p.fail('unterminated table header')
        p.i++
      }
      p.ws()
      if (!p.atEnd()) p.fail('trailing text after a table header')
      let t = root
      const path = []
      for (let k = 0; k < names.length - 1; k++) {
        path.push(names[k])
        let next = t.m.get(names[k])
        if (next === undefined) {
          next = newTable()
          t.m.set(names[k], next)
        } else if (next.type === 'array' && next.aot) {
          next = next.items[next.items.length - 1]
        } else if (next.type !== 'table') {
          p.fail(`${path.join('.')} is not a table`)
        }
        t = next
      }
      const last = names[names.length - 1]
      path.push(last)
      const ps = path.join('.')
      const ex = t.m.get(last)
      if (aot) {
        let arr = ex
        if (ex === undefined) {
          arr = { type: 'array', items: [], aot: true }
          t.m.set(last, arr)
        } else if (ex.type !== 'array' || !ex.aot) {
          p.fail(`${ps} is not an array of tables`)
        }
        const nt = newTable()
        arr.items.push(nt)
        cur = nt
      } else {
        if (ex === undefined) {
          const nt = newTable()
          nt.defined = true
          t.m.set(last, nt)
          cur = nt
        } else if (ex.type !== 'table') {
          p.fail(`${ps} is not a table`)
        } else {
          if (ex.defined) p.fail(`table ${ps} is defined twice`)
          ex.defined = true
          cur = ex
        }
      }
      curPath = path
      return
    }
    const names = p.dotted()
    p.ws()
    if (p.peek() !== '=') p.fail('expected key = value')
    p.i++
    p.ws()
    const v = p.value([...curPath, ...names.slice(0, -1)].slice(0, 0).concat(curPath, names))
    p.ws()
    if (!p.atEnd()) p.fail('trailing text after a value')
    assign(cur, curPath, names, v, p)
  })
  return root
}
